/**
 * Turns an API surface (routes with method, path, operation and authentication) into an
 * OpenAPI 3.1 document. Test-side tooling: the documents are generated by
 * api-surface.unit.test.ts into docs/api/ and compared there, never written by hand.
 */

export interface SurfaceRoute {
	/** An HTTP method, or "*" for a route that takes any. */
	method: string;
	/** Express-style (`/a/:id`, `/a/*rest`) or already templated (`/a/{id}`). */
	path: string;
	operation: string | null;
	/** A key of the document's security schemes, or "public". */
	auth: string;
	/** A pass-through to another surface (the control plane's proxy to the monitor). */
	forwards?: string;
	/** A regular expression the route really matches, when the template is a reading of it. */
	pattern?: string;
}

export interface SecurityScheme {
	type: "http" | "apiKey";
	scheme?: "bearer";
	in?: "header" | "cookie" | "query";
	name?: string;
	description: string;
}

export interface SurfaceDoc {
	title: string;
	description: string;
	/** auth value → the schemes that satisfy it (any one of them). */
	auth: Record<string, { schemes: string[]; description: string }>;
	schemes: Record<string, SecurityScheme>;
	routes: SurfaceRoute[];
}

const ANY_METHOD = ["get", "post", "put", "patch", "delete"];

/** `/a/:id/*rest` → `/a/{id}/{rest}`. */
export function templatePath(path: string): string {
	return path.replace(/:(\w+)/g, "{$1}").replace(/\*(\w+)/g, "{$1}");
}

/**
 * A monitor route's regular expression as a path template: each capture group becomes a
 * parameter named after the segment before it (`/agents/([^/]+)` → `/agents/{agent}`).
 * Returns null for an expression it cannot read as a path.
 */
export function templateFromRegExp(re: RegExp): string | null {
	let src = re.source.replace(/^\^/, "").replace(/\$$/, "");
	if (/[|?*]|\(\?/.test(src.replace(/\([^)]*\)/g, ""))) return null;
	src = src.replace(/\\\//g, "/");
	let out = "";
	let last = 0;
	for (const m of src.matchAll(/\(([^)]*)\)/g)) {
		out += src.slice(last, m.index);
		last = (m.index ?? 0) + m[0].length;
		const prev = out.split("/").filter(Boolean).pop() ?? "";
		// A choice of words (`(start|stop)`) is the action; otherwise the segment it follows names it.
		const name =
			/^[a-z|]+$/.test(m[1]) && m[1].includes("|")
				? "action"
				: prev && !prev.startsWith("{")
					? prev.replace(/s$/, "")
					: `param${out.split("{").length}`;
		out += `{${name}}`;
	}
	out += src.slice(last);
	return /^\/[\w{}./-]*$/.test(out) ? out : null;
}

function pathParams(path: string): string[] {
	return [...path.matchAll(/\{(\w+)\}/g)].map((m) => m[1]);
}

/** One method of one route, as an OpenAPI operation object. */
function operationObject(
	r: SurfaceRoute,
	method: string,
	path: string,
	schemes: string[],
): Record<string, unknown> {
	const params = pathParams(path);
	return {
		operationId: `${method}${path.replace(/[{}]/g, "").replace(/[^\w]+(\w)?/g, (_x, c: string | undefined) => (c ?? "").toUpperCase())}`,
		...(r.operation ? { "x-magi-operation": r.operation } : {}),
		"x-magi-auth": r.auth,
		...(r.method === "*" ? { "x-magi-any-method": true } : {}),
		...(r.forwards ? { "x-magi-forwards": r.forwards } : {}),
		...(r.pattern ? { "x-magi-pattern": r.pattern } : {}),
		security: schemes.map((s) => ({ [s]: [] })),
		...(params.length
			? {
					parameters: params.map((name) => ({
						name,
						in: "path",
						required: true,
						schema: { type: "string" },
					})),
				}
			: {}),
		...(["post", "put", "patch"].includes(method)
			? {
					requestBody: {
						required: false,
						content: { "application/json": { schema: { type: "object" } } },
					},
				}
			: {}),
		responses: { default: { description: "See the route's code." } },
	};
}

export function toOpenApi(doc: SurfaceDoc): Record<string, unknown> {
	const paths: Record<string, Record<string, unknown>> = {};
	for (const r of doc.routes) {
		const path = templatePath(r.path);
		const methods = r.method === "*" ? ANY_METHOD : [r.method.toLowerCase()];
		const auth = doc.auth[r.auth];
		if (!auth)
			throw new Error(`route ${r.method} ${r.path}: unknown auth "${r.auth}"`);
		const item = paths[path] ?? {};
		paths[path] = item;
		for (const m of methods) {
			if (!item[m]) item[m] = operationObject(r, m, path, auth.schemes);
		}
	}
	const sorted = Object.fromEntries(
		Object.entries(paths).sort(([a], [b]) => a.localeCompare(b)),
	);
	return {
		openapi: "3.1.0",
		info: {
			title: doc.title,
			version: "generated",
			description: `${doc.description}\n\nGenerated from the code by packages/control-plane/tests/api-surface.unit.test.ts (npm run docs:api); do not edit. Request bodies are declared as objects until the route's Zod schema is attached.\n\nAuthentication:\n${Object.entries(
				doc.auth,
			)
				.map(([k, v]) => `- \`${k}\`: ${v.description}`)
				.join("\n")}`,
		},
		paths: sorted,
		components: { securitySchemes: doc.schemes },
	};
}
